// ===== utilitários padrão Konext (iguais em todos os fluxos) =====
const n_ = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, nomes) => {
  const m = {};
  for (const k of Object.keys(row || {})) m[n_(k)] = row[k];
  for (const nome of nomes) { const v = m[n_(nome)]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); }
  return '';
};
const dig = v => String(v ?? '').replace(/\D/g, '');
const sim = (v, padrao) => { const t = n_(v); if (!t) return padrao; return ['sim', 's', 'yes', 'y', 'true', '1', 'ativo'].includes(t); };
const nao = v => ['nao', 'n', 'no', 'false', '0', 'inativo'].includes(n_(v));
const money = v => {
  let s = String(v ?? '').replace(/[^\d,.\-]/g, '');
  if (!s) return null;
  const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > -1 && p > -1) s = c > p ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (c > -1) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s); return isNaN(n) ? null : n;
};
// Número de WhatsApp ou ID de grupo -> formato aceito pela Evolution API
const jid = v => {
  const s = String(v ?? '').trim();
  if (!s) return '';
  if (/@g\.us$/i.test(s)) return s.replace(/\s/g, '');
  const d = s.replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('120363') && d.length >= 15) return d + '@g.us';
  return d.length <= 11 ? '55' + d : d;
};

const cfg = $('Config (Saldo)').first().json;
const preferirGrupo = !(cfg.preferir_grupo === false || cfg.preferir_grupo === 'false');
const grupos = $('Grupos WhatsApp (Saldo)').all().map(i => i.json || {}).filter(g => !g.error)
  .map(g => ({ nome: pick(g, ['Grupo', 'Nome do Grupo', 'Nome']), id: pick(g, ['ID', 'ID do Grupo']).replace(/\s/g, ''), ativo: !nao(pick(g, ['Ativo'])) }))
  .filter(g => g.ativo && /@g\.us$/i.test(g.id))
  .map(g => ({ ...g, chave: n_(g.nome) }));
// Procura o grupo do cliente pelo nome / apelidos (só aceita quando há UM grupo compatível)
const acharGrupo = (cliente, apelidos) => {
  const cands = [cliente, ...apelidos].map(n_).filter(c => c.length >= 4);
  let m = grupos.filter(g => cands.some(c => g.chave.includes(c)));
  if (m.length === 1) return m[0];
  if (m.length > 1) return null;
  const primeiro = n_(String(cliente).trim().split(/\s+/)[0]);
  if (primeiro.length >= 4) { m = grupos.filter(g => g.chave.includes(primeiro)); if (m.length === 1) return m[0]; }
  return null;
};
// Destino: grupo do cliente (coluna "ID do Grupo" ou planilha de grupos) e, se não houver, o "Contato do cliente".
// O "Contato do cliente" também pode conter direto um ID de grupo (120363...@g.us).
const montarDestino = (cliente, apelidos, contatoRaw, grupoRaw) => {
  const contato = jid(contatoRaw);
  const fixo = jid(grupoRaw);
  const g = fixo.endsWith('@g.us') ? { id: fixo, nome: '(ID do Grupo na planilha)' } : acharGrupo(cliente, apelidos);
  let destino = '', destino_desc = '';
  const porGrupo = () => { destino = g.id; destino_desc = 'grupo ' + g.nome; };
  const porContato = () => { destino = contato; destino_desc = (contato.endsWith('@g.us') ? 'grupo ' : 'WhatsApp ') + contato; };
  if (preferirGrupo) { if (g) porGrupo(); else if (contato) porContato(); }
  else { if (contato) porContato(); else if (g) porGrupo(); }
  return { contato, grupo: g ? g.id : '', grupo_nome: g ? g.nome : '', destino, destino_desc };
};
const clientes = []; const vistos = new Set();
for (const it of $('Clientes Geral (Saldo)').all()) {
  const r = it.json || {};
  if (r.error) continue;
  if (!sim(pick(r, ['Status', 'Ativo']), false)) continue;           // Status = Ativo
  const conta = dig(pick(r, ['ID da Conta', 'Conta de Anuncio', 'Conta de Anúncio', 'Conta']));
  const cliente = pick(r, ['Cliente', 'Clientes', 'Nome do cliente', 'Nome']);
  if (!conta || vistos.has(conta)) continue;
  vistos.add(conta);
  const apelidos = pick(r, ['Apelido', 'Apelidos']).split(',').map(s => s.trim()).filter(Boolean);
  clientes.push({
    row_number: r.row_number, cliente: cliente || ('Conta ' + conta), conta, apelidos,
    ...montarDestino(cliente, apelidos, pick(r, ['Contato do cliente', 'Contato', 'WhatsApp do cliente', 'Telefone']), pick(r, ['ID do Grupo', 'Grupo WhatsApp', 'Grupo do cliente'])),
    valor_base: money(pick(r, ['Valor Base'])),
    reativar: sim(pick(r, ['Reativar na Segunda', 'Reativar toda segunda', 'Reativar toda segunda-feira', 'Reativar']), true),
    monitorar: sim(pick(r, ['Monitorar Custo']), true),
    pagina: dig(pick(r, ['ID da Página', 'ID da Pagina'])),
    ig_id: dig(pick(r, ['ID Instagram', 'ID do Instagram'])),
    ig_user: pick(r, ['Instagram (usuário)', 'Usuário do Instagram', 'Instagram']).replace(/^@/, ''),
    whatsapp_campanha: jid(pick(r, ['WhatsApp da Campanha', 'WhatsApp'])),
    link_relatorio: pick(r, ['Link do Relatório', 'Link do Relatorio', 'Link Relatório', 'Relatório', 'Link do Dashboard']),
    enviar_relatorio: sim(pick(r, ['Enviar Relatório', 'Enviar Relatorio']), true),
    rel_melhorias: pick(r, ['Relatório - Melhorias', 'Melhorias']),
    rel_ajustes: pick(r, ['Relatório - Ajustes', 'Ajustes']),
  });
}

const painel = $input.all().map(i => i.json || {}).filter(r => !r.error && r.row_number);
const porConta = new Map();
for (const p of painel) { const c = dig(pick(p, ['Conta de Anuncio', 'Conta de Anúncio', 'ID da Conta'])); if (c && !porConta.has(c)) porConta.set(c, p); }
const out = []; const usados = new Set();
for (const c of clientes) {
  usados.add(c.conta);
  const p = porConta.get(c.conta);
  if (p && nao(pick(p, ['Ativo']))) continue;              // desligado na planilha de saldo
  out.push({ json: { ...c, saldo_row: p ? p.row_number : null,
    metodo: p ? pick(p, ['Metodo de Pagamento', 'Método de Pagamento']) : '',
    valor_base: c.valor_base ?? (p ? money(pick(p, ['Valor Base'])) : null) } });
}
// clientes que só existem na planilha de saldo (Ativo = Sim) também são verificados
for (const [conta, p] of porConta) {
  if (usados.has(conta) || !sim(pick(p, ['Ativo']), false)) continue;
  const cliente = pick(p, ['Clientes', 'Cliente']) || ('Conta ' + conta);
  out.push({ json: { row_number: null, cliente, conta, apelidos: [],
    ...montarDestino(cliente, [], pick(p, ['Contato do cliente', 'Contato']), ''),
    saldo_row: p.row_number, metodo: pick(p, ['Metodo de Pagamento', 'Método de Pagamento']),
    valor_base: money(pick(p, ['Valor Base'])), so_na_planilha_saldo: true } });
}
return out;

// ===== utilitários padrão Konext (iguais em todos os fluxos) =====
const n_ = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, nomes) => {
  const m = {};
  for (const k of Object.keys(row || {})) m[n_(k)] = row[k];
  for (const nome of nomes) { const v = m[n_(nome)]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); }
  return '';
};
