const sim = (v, padrao) => { const t = n_(v); if (!t) return padrao; return ['sim', 's', 'yes', 'y', 'true', '1', 'ativo'].includes(t); };
const nao = v => ['nao', 'n', 'no', 'false', '0', 'inativo'].includes(n_(v));
const money = v => {
  let s = String(v ?? '').replace(/[^\d,.\-]/g, '');
  if (!s) return null;
  const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > -1 && p > -1) s = c > p ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (c > -1) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s); return isNaN(n) ? null : n;
};
// Número de WhatsApp ou ID de grupo -> formato aceito pela Evolution API
const jid = v => {
  const s = String(v ?? '').trim();
  if (!s) return '';
  if (/@g\.us$/i.test(s)) return s.replace(/\s/g, '');
  const d = s.replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('120363') && d.length >= 15) return d + '@g.us';
  return d.length <= 11 ? '55' + d : d;
};

const cli = $('Loop Over Items').item.json;
const r = $input.item.json;
const num = v => { const n = parseFloat(v); return isNaN(n) ? null : n; };
const brl = n => 'R$ ' + n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const h = parseInt($now.toFormat('HH'), 10);
const saudacao = h < 12 ? 'Bom dia' : (h < 18 ? 'Boa tarde' : 'Boa noite');

const sd = $getWorkflowStaticData('global');
const ek = String($execution.id);
sd.resumo = sd.resumo || {};
for (const k of Object.keys(sd.resumo)) if (k !== ek) delete sd.resumo[k];
sd.resumo[ek] = sd.resumo[ek] || [];
const reg = (status, saldo, obs) => sd.resumo[ek].push({ cliente: cli.cliente || cli.conta, status, saldo, obs: obs || '' });
const erro = t => { reg('erro', null, t); return { json: { acao: 'erro', cliente: cli.cliente, conta: cli.conta, erro: t } }; };

if (r.error || !r.id) {
  let e = r.error; if (e && typeof e === 'object') e = e.message || JSON.stringify(e);
  if (/credential/i.test(JSON.stringify(r))) return erro('Credencial do Facebook Graph não selecionada no nó Meta Ads do n8n (não é problema do cliente).');
  return erro('Falha ao consultar a Meta (token sem acesso à conta?): ' + String(e ?? JSON.stringify(r)).slice(0, 250));
}
const nome = (cli.cliente || r.name || r.business_name || '').trim();
if (!nome) return erro('Cliente sem nome na planilha e sem nome na conta de anúncios.');

const semBase = cli.valor_base === null || cli.valor_base === undefined || cli.valor_base <= 0;
const met = n_(cli.metodo);
const prepago = /pix|boleto|prepag/.test(met) ? true : (/cartao|credito|card/.test(met) ? false : (r.is_prepay_account === true || r.is_prepay_account === 'true'));
let saldo, alertar, mensagem, origem = '';
if (prepago) {
  // 1º: saldo disponível informado pela Meta (funding_source_details); 2º: limite de gastos - gasto
  const disp = String((r.funding_source_details || {}).display_string || '');
  const m = disp.match(/\(([^)]*\d[^)]*)\)/);
  const viaFonte = m ? money(m[1]) : null;
  const cap = num(r.spend_cap), gasto = num(r.amount_spent);
  if (viaFonte !== null) { saldo = viaFonte; origem = 'saldo disponível da Meta'; }
  else if (cap !== null && cap > 0 && gasto !== null) { saldo = (cap - gasto) / 100; origem = 'limite de gastos - gasto'; }
  else return erro('Conta pré-paga: a Meta não retornou o saldo disponível e a conta não tem limite de gastos (spend_cap).');
  alertar = !semBase && saldo < cli.valor_base;
  mensagem = `${saudacao}!\n\n🚨 *Aviso Importante:*\n\nA conta *${nome}* está com saldo de *${brl(saldo)}*.\n\n⚠️ Precisamos de uma recarga para garantir que os anúncios continuem sendo veiculados.\n\nPosso gerar o código Pix para te enviar?\n\n— Equipe Konext`;
} else {
  const bal = num(r.balance);
  if (bal === null) return erro('A Meta não retornou o campo balance da conta.');
  saldo = bal / 100;
  alertar = !semBase && saldo > cli.valor_base;
  mensagem = `${saudacao}!\n\n🚨 *Aviso Importante:*\n\nA conta *${nome}* está perto da próxima cobrança. Já foram investidos *${brl(saldo)}*.\n\nVerifique seu *cartão* para que não falte saldo para o pagamento.\n\n— Equipe Konext`;
}
const obs = [];
if (semBase) obs.push('sem Valor Base (saldo registrado, sem aviso)');
if (!cli.saldo_row) obs.push('cliente sem linha na planilha de saldo (saldo não gravado)');
if (cli.so_na_planilha_saldo) obs.push('não está ativo na Planilha Geral');
if (alertar && !cli.destino) { alertar = false; obs.push('precisava de aviso, mas está sem grupo/contato na planilha'); }
if (alertar) obs.push('aviso para ' + cli.destino_desc);
reg(alertar ? 'alertar' : 'ok', saldo, obs.join('; '));
return { json: { acao: alertar ? 'alertar' : 'ok', cliente: nome, conta: cli.conta, destino: cli.destino, destino_desc: cli.destino_desc,
                 tipo: prepago ? 'prepago' : 'cartao', saldo, row_number: cli.saldo_row, mensagem } };

const a = $('Avaliar Saldo').first().json;
let e = $input.first().json.error; if (e && typeof e === 'object') e = e.message || JSON.stringify(e);
const sd = $getWorkflowStaticData('global'); const lista = (sd.resumo || {})[String($execution.id)] || [];
const rec = lista.find(x => x.cliente === a.cliente); if (rec) rec.obs = (rec.obs ? rec.obs + '; ' : '') + 'FALHA NO ENVIO';
return [{ json: { cliente: a.cliente, conta: a.conta, erro: 'Falha ao enviar o WhatsApp ao cliente (' + a.destino_desc + '): ' + String(e ?? 'erro desconhecido').slice(0, 250) } }];

