const sd = $getWorkflowStaticData('global');
const ek = String($execution.id);
const lista = (sd.resumo && sd.resumo[ek]) || [];
if (sd.resumo) delete sd.resumo[ek];
if (!lista.length) return [];
const brl = n => 'R$ ' + n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const icone = { alertar: '🚨', ok: '✅', erro: '⚠️' };
const linhas = lista.map(x => `${icone[x.status] || '•'} *${x.cliente}* — ${x.saldo === null ? 'sem saldo' : brl(x.saldo)}${x.status === 'alertar' ? ' (alerta enviado)' : ''}${x.obs ? ' — ' + x.obs : ''}`);
const alertas = lista.filter(x => x.status === 'alertar').length;
const erros = lista.filter(x => x.status === 'erro').length;
const mensagem = `📊 *Resumo da verificação de saldo (Konext)*\n\n${linhas.join('\n')}\n\nClientes verificados: ${lista.length} | Alertas: ${alertas} | Com problema: ${erros}`;
return [{ json: { mensagem } }];
